<template>
<view class="page">
  <view class="nav"><text @click="back">‹ {{ tr('Back') }}</text><text>{{ tr('Signal analysis') }}</text><text class="refresh" @click="load">↻</text></view>
  <view class="hero"><view class="hero-caption"><text>{{ tr('Latest measurement waveform') }}</text><text class="signal-icon">⌁</text></view><text class="hero-time">{{ receivedTime }}</text><text class="hero-note">{{ tr('Signal overview, filtering and detail') }}</text></view>
  <view v-if="loading" class="loading">{{ tr('Refreshing the latest saved signal') }}</view>
  <view v-if="!wave&&!loading" class="empty"><text>⌁</text><text>{{ tr('No signal saved yet') }}</text><text>{{ tr('Complete a measurement to see its signal here') }}</text><button @click="load">{{ tr('Refresh') }}</button></view>
  <template v-if="wave">
    <view class="overview"><view><text>{{ tr('Duration') }}</text><text class="value">{{ wave.duration.toFixed(2) }} <text>s</text></text></view><view><text>{{ tr('Sample rate') }}</text><text class="value">{{ (wave.sampleRate/1000).toFixed(1) }} <text>kHz</text></text></view><view><text>{{ tr('Sample count') }}</text><text class="value">{{ wave.samples.toLocaleString() }}</text></view></view>
    <view class="card"><view class="card-head"><view><text class="title">{{ tr('Full recording') }}</text><text class="subtitle">{{ tr('Amplitude') }} · mV</text></view><text class="pill">{{ wave.duration.toFixed(2) }} s</text></view>
      <view class="tabs"><text :class="{active:mode==='filtered'}" @click="mode='filtered'">{{ tr('Filtered signal') }}</text><text :class="{active:mode==='raw'}" @click="mode='raw'">{{ tr('Raw signal') }}</text></view>
      <MeasurementChart :show-markers="false" chart-id="fullSignal" :labels="signal.map(p=>p.time.toFixed(3)+' s')" :x-values="signal.map(p=>p.time)" :series="[{name:tr(mode==='filtered'?'Filtered signal':'Raw signal'),color:mode==='filtered'?'#7763df':'#45a6b4',data:signal.map(p=>p.value)}]" :minimum-span="0.01" />
      <text class="foot">{{ tr('Tap the curve to inspect a sample') }}</text>
    </view>
    <view class="card"><view class="card-head"><view><text class="title">{{ tr('Local zoom') }}</text><text class="subtitle">{{ tr('Select a section to inspect') }}</text></view><text class="pill">mV</text></view>
      <view class="zoom-options"><text v-for="size in [0.08,1,2]" :key="size" :class="{active:windowSize===size}" @click="setWindow(size)">{{ size }} s</text></view>
      <MeasurementChart :show-markers="false" chart-id="zoomSignal" :labels="zoomPoints.map(p=>p.time.toFixed(3)+' s')" :x-values="zoomPoints.map(p=>p.time)" :series="[{name:tr('Filtered signal'),color:'#df8390',data:zoomPoints.map(p=>p.value)}]" :minimum-span="0.01" />
      <view class="window-label"><text>{{ tr('Time') }}</text><text>{{ zoomStart.toFixed(2) }} – {{ Math.min(wave.duration,zoomStart+windowSize).toFixed(2) }} s</text></view><slider :value="zoomStart*1000" :max="Math.max(1,Math.floor((wave.duration-Math.min(windowSize,wave.duration))*1000))" :step="10" activeColor="#8c78e2" backgroundColor="#eceaf5" block-size="18" @change="zoomStart=$event.detail.value/1000" />
    </view>
    <view class="card"><text class="title">{{ tr('Signal details') }}</text><view class="amplitudes"><view><text class="subtitle">{{ tr('Peak-to-peak') }}</text><text class="amplitude">{{ statistic('peakToPeak') }} <text>mV</text></text></view><view><text class="subtitle">{{ tr('Effective amplitude') }}</text><text class="amplitude">{{ statistic('rms') }} <text>mV</text></text></view></view><view class="processing"><view class="processing-dot"/><view><text>{{ tr('4th-order zero-phase bandpass') }}</text><text>{{ wave.filter.low }} – {{ wave.filter.high }} Hz</text></view></view><text class="foot">{{ tr('Raw signal is shown after DC removal') }}</text></view>
    <view class="explanation">{{ tr('Time axis in seconds; display preserves peaks. This is an interference signal, not a blood pressure curve.') }}</view>
  </template>
</view>
</template>
<script>
import MeasurementChart from '@/components/MeasurementChart.vue';
import {getDataUrl} from '@/config/api.js';
export default {
  components:{MeasurementChart},data:()=>({wave:null,loading:false,mode:'filtered',windowSize:0.08,zoomStart:0,loadVersion:0}),onShow(){this.load();},onUnload(){this.loadVersion++;},
  computed:{signal(){return this.wave?.[this.mode]||[];},zoomPoints(){if(!this.wave)return [];if(this.zoomStart===0&&this.windowSize===0.08)return this.wave.zoom;const end=this.zoomStart+this.windowSize;return this.wave.filtered.filter(p=>p.time>=this.zoomStart&&p.time<=end);},receivedTime(){if(!this.wave)return '--';const d=new Date(this.wave.receivedAt);if(!Number.isFinite(d.getTime()))return '--';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;}},
  methods:{back(){uni.navigateBack();},statistic(key){const value=this.wave?.statistics?.[key];return Number.isFinite(value)?value.toFixed(2):'--';},setWindow(size){this.windowSize=size;this.zoomStart=Math.min(this.zoomStart,Math.max(0,this.wave.duration-size));},load(){const version=++this.loadVersion;this.loading=true;const user=uni.getStorageSync('user'),deviceId=uni.getStorageSync('selectedDeviceId'),key='latestWaveform_'+user?.id+'_'+deviceId;if(!this.wave)this.wave=uni.getStorageSync(key)||null;uni.request({url:getDataUrl('waveform'),data:{deviceId},success:res=>{if(version!==this.loadVersion)return;if(res.data.errcode===0&&res.data.data){this.wave=res.data.data;uni.setStorageSync(key,this.wave);this.zoomStart=0;}},fail:()=>uni.showToast({title:this.tr('Network error'),icon:'none'}),complete:()=>{if(version===this.loadVersion)this.loading=false;}});}}
};
</script>
<style scoped>
