x;border-radius:16rpx}.zoom-options>text.active{color:#8772d4;background:#eeebfa}.window-label{display:flex;justify-content:space-between;color:#929cb0;font-size:24rpx;margin-top:20rpx}.amplitudes{display:flex;padding:30rpx 0;margin-top:16rpx;border-bottom:1px solid #f2f3f7}.amplitudes>view{flex:1}.amplitude{display:block;font-size:37rpx;font-weight:600;margin-top:12rpx;color:#7d6bc4}.amplitude>text{font-size:22rpx;color:#a1a8b7;font-weight:400}.processing{display:flex;gap:18rpx;align-items:center;padding-top:28rpx}.processing-dot{height:14rpx;width:14rpx;border-radius:50%;background:#6bbbaa}.processing text{display:block;font-size:25rpx;color:#798399;line-height:1.8}.processing text:last-child{font-size:23rpx;color:#a0a7b5}.explanation{font-size:22rpx;color:#9aa3b3;line-height:1.8;margin:24rpx 8rpx}.empty{text-align:center;background:white;border-radius:28rpx;padding:70rpx 30rpx;margin-top:28rpx}.empty>text{display:block;margin:16rpx 0;font-size:26rpx;color:#8b95aa}.empty>text:first-child{font-size:90rpx;color:#b1a1e6}.empty button{margin-top:30rpx;background:#eeeafa;color:#8571cb;border-radius:20rpx;font-size:26rpx}.loading{text-align:center;padding-top:24rpx;color:#a1a8b7;font-size:22rpx}
</style>